    }

    /** A period's due-total: the due figures of the claims that count whose date falls in it,
     *  skipping those with no due and those that do not count live (see Dues#countsLive). */
    private BigDecimal dueTotal(String sheetId, Period period) {
        Map<Long, Person> byId = people.findBySheetIdOrderByIdAsc(sheetId).stream()
                .collect(Collectors.toMap(Person::getId, Function.identity()));
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        for (Claim c : claims.findBySheetIdOrderByListedDesc(sheetId)) {
            Person person = byId.get(c.getPersonId());
            if (person == null || !Dues.countsLive(person, c) || c.getDate().isBefore(period.getFromDate())
                    || c.getDate().isAfter(period.getToDate())) {
                continue;
            }
            BigDecimal figure = dues.figure(sheetId, person, c);
            if (figure != null) {
                total = total.add(figure);
            }
        }
        return total;
    }

    private static ResponseStatusException nameInUse() {
        return new ResponseStatusException(HttpStatus.CONFLICT, "That period name is already in use on this sheet");
    }
}
import { HttpErrorResponse } from '@angular/common/http';
import { Component, inject, input, output, signal } from '@angular/core';
import { FormControl, FormGroup, ReactiveFormsModule } from '@angular/forms';
import { Period, Periods } from '../../core/periods';

const DAY = /^\d{4}-\d{2}-\d{2}$/;

// The periods on the sheet with each one's due-total, and the form that adds a period.
@Component({
  selector: 'app-period-form',
  imports: [ReactiveFormsModule],
  template: `
    <section aria-labelledby="periods-heading">
      <h2 id="periods-heading">Periods</h2>
      <form data-testid="period-form" [formGroup]="form" (ngSubmit)="submit()">
        <label for="period-form-name">Name</label>
        <input id="period-form-name" data-testid="period-form-name" formControlName="name" />
        <label for="period-form-from">From</label>
        <input id="period-form-from" type="date" data-testid="period-form-from" formControlName="from" />
        <label for="period-form-to">To</label>
        <input id="period-form-to" type="date" data-testid="period-form-to" formControlName="to" />
        <button type="submit" data-testid="period-form-submit">Add period</button>
        @if (error()) {
          <p role="alert" data-testid="period-form-error">{{ error() }}</p>
        }
      </form>
      <table data-testid="periods">
        <thead>
          <tr><th scope="col">Name</th><th scope="col">From</th><th scope="col">To</th><th scope="col">Due</th><th scope="col">Closed</th><th scope="col"><span class="visually-hidden">Actions</span></th></tr>
        </thead>
        <tbody>
          @for (p of periods(); track p.id) {
            <tr [attr.data-testid]="'period-row-' + p.name">
              <th scope="row" data-testid="period-name">{{ p.name }}</th>
              <td data-testid="period-from">{{ p.from }}</td>
              <td data-testid="period-to">{{ p.to }}</td>
              <td data-testid="period-due-total">{{ p.closedTotal ?? dueTotals().get(p.id) ?? '0.00' }}</td>
              <td data-testid="period-closed">{{ p.closed ? 'yes' : 'no' }}</td>
              <td>
                @if (!p.closed) {
                  <button type="button" data-testid="period-close" (click)="close(p)"
                    [attr.aria-label]="'Close period ' + p.name">Close</button>
                }
                <button type="button" data-testid="period-reopen" (click)="reopen(p)"
                  [attr.aria-label]="'Reopen period ' + p.name">Reopen</button>
                @if (periodError()?.id === p.id) {
                  <p role="alert" data-testid="period-error">{{ periodError()?.message }}</p>
                }
              </td>
            </tr>
          }
        </tbody>
      </table>
    </section>
  `,
})
export class PeriodForm {
  private readonly api = inject(Periods);

  /** The periods on the sheet, earliest first. */
  readonly periods = input.required<Period[]>();
  /** Each period's due-total by its id. */
  readonly dueTotals = input.required<Map<number, string>>();
  /** A period added through the form, or closed or reopened from its row. */
  readonly saved = output<Period>();

  protected readonly error = signal('');
  /** The refusal of the last action taken on a period's row, shown on that row. */
  protected readonly periodError = signal<{ id: number; message: string } | null>(null);
  /** Whether a submit is waiting for its answer: a second submit meanwhile is ignored. */
  private submitting = false;
  protected readonly form = new FormGroup({
    name: new FormControl('', { nonNullable: true }),
    from: new FormControl('', { nonNullable: true }),
    to: new FormControl('', { nonNullable: true }),
  });

  constructor() {
    this.form.valueChanges.subscribe(() => this.error.set(''));
  }

  protected async close(p: Period): Promise<void> {
    this.periodError.set(null);
    try {
      this.saved.emit(await this.api.close(p.id));
    } catch {
      this.periodError.set({ id: p.id, message: 'The period could not be closed.' });
    }
  }

  protected async reopen(p: Period): Promise<void> {
    this.periodError.set(null);
    try {
      this.saved.emit(await this.api.reopen(p.id));
    } catch (e) {
      this.periodError.set({
        id: p.id,
        message:
          e instanceof HttpErrorResponse && e.status === 403
            ? 'Only a steward may reopen a period.'
            : 'The period could not be reopened.',
      });
    }
  }

  protected async submit(): Promise<void> {
    if (this.submitting) return;
    this.error.set('');
    const { name, from, to } = this.form.getRawValue();
    if (!name.trim()) {
      this.error.set('Enter a name.');
      return;
    }
    if (!DAY.test(from.trim()) || !DAY.test(to.trim())) {
      this.error.set('Enter the day the period runs from and the day it runs to.');
      return;
    }
    if (to.trim() < from.trim()) {
      this.error.set('A period cannot end before it starts.');
      return;
    }
    this.submitting = true;
    try {
      this.saved.emit(await this.api.add({ name: name.trim(), from: from.trim(), to: to.trim() }));
      this.form.reset({ name: '', from: '', to: '' }, { emitEvent: false });
    } catch (e) {
      this.error.set(
        e instanceof HttpErrorResponse && e.status === 409
          ? 'That name is in use, or the period overlaps another on this sheet.'
          : 'The period could not be added.',
      );
    } finally {
      this.submitting = false;
    }
  }
}
import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Session } from './session';

export interface Period {
  id: number;
  /** Unique on the sheet. */
  name: string;
  /** The first day (yyyy-mm-dd) of the period. */
  from: string;
  /** The last day (yyyy-mm-dd) of the period. */
  to: string;
  /** Whether the period is closed: no claim dated inside it can be changed. */
  closed: boolean;
  /** The due-total fixed when it was closed, as text with two decimals; null while it is open. */
  closedTotal: string | null;
}

export interface PeriodForm {
  name: string;
  from: string;
  to: string;
}

/** The period whose days contain the day, or undefined when there is none. */
export function periodOf(periods: Period[], day: string): Period | undefined {
  return periods.find((p) => p.from <= day && day <= p.to);
}

// The periods on the active sheet.
@Injectable({ providedIn: 'root' })
export class Periods {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  /** The periods on the sheet, earliest first. */
  list(sheetId: string): Promise<Period[]> {
    return firstValueFrom(this.http.get<Period[]>(this.url(sheetId)));
  }

  /** Add a period; refused when it ends before it starts, its name is in use or it overlaps another. */
  add(form: PeriodForm): Promise<Period> {
    const sheetId = this.session.sheetId();
    const user = this.session.user();
    if (!sheetId || !user) throw new Error('no sheet loaded');
    return firstValueFrom(this.http.post<Period>(this.url(sheetId), form, { headers: { 'X-User': user } }));
  }

  /** Close a period, fixing its due-total; refused when it is already closed. */
  close(id: number): Promise<Period> {
    const sheetId = this.session.sheetId();
    const user = this.session.user();
    if (!sheetId || !user) throw new Error('no sheet loaded');
    return firstValueFrom(
      this.http.post<Period>(`${this.url(sheetId)}/${id}/close`, null, { headers: { 'X-User': user } }),
    );
  }

  /** Reopen a closed period, making its due-total live again; refused when the user is not a
   *  steward or the period is not closed. */
  reopen(id: number): Promise<Period> {
    const sheetId = this.session.sheetId();
    const user = this.session.user();
    if (!sheetId || !user) throw new Error('no sheet loaded');
    return firstValueFrom(
      this.http.post<Period>(`${this.url(sheetId)}/${id}/reopen`, null, { headers: { 'X-User': user } }),
    );
  }

  private url(sheetId: string): string {
    return `/api/sheets/${encodeURIComponent(sheetId)}/periods`;
  }
}
-- A period on a sheet: a name, unique on the sheet without regard to case, and the days it runs
-- from and to, both inclusive. No two periods of a sheet overlap.
CREATE TABLE period (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    name      VARCHAR(100) NOT NULL,
    name_key  VARCHAR(100) GENERATED ALWAYS AS (LOWER(TRIM(name))),
    from_date DATE         NOT NULL,
    to_date   DATE         NOT NULL,
    CONSTRAINT period_dates CHECK (from_date <= to_date),
    CONSTRAINT period_sheet_name_unique UNIQUE (sheet_id, name_key)
);
CREATE INDEX period_sheet ON period (sheet_id, from_date);
-- Whether a period is closed, and the due-total it had when it was closed, kept so later changes
-- to rates do not alter it. No claim dated inside a closed period can be added, edited or change
-- its status.
ALTER TABLE period ADD COLUMN closed BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE period ADD COLUMN closed_total DECIMAL(14, 2);

